use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut result = 0;
    let mut mask = 1;

    while let Some(value) = input.as_u32() {
        if value & mask == 0 {
            result = result | mask;
        }
        mask <<= 1;
    }

    if result == 0 {
        -1
    } else {
        result as i64
    }
}
